const raw = $input.first().json;
let data = raw;
if (raw.body !== undefined) {
  let rawBody = raw.body;
  if (typeof rawBody === 'string') { rawBody = rawBody.replace(/^=+/, '').trim(); try { data = JSON.parse(rawBody); } catch(e) { data = raw; } }
  else if (typeof rawBody === 'object') { data = rawBody; }
}
const task_id   = data.task_id || raw.task_id || 'TASK-KNOWLEDGE-' + Date.now();
const operation = String(data.operation || raw.operation || 'WRITE').toUpperCase();
const kind      = String(data.kind || data.category || raw.category || 'pattern');
const project   = String(data.project || (data.data && data.data.project) || '');
const meta      = (data.meta && typeof data.meta === 'object') ? data.meta : {};
let text = '';
if (operation === 'READ') { text = data.query || data.text || ''; }
else { text = data.text || (typeof data.data === 'string' ? data.data : (data.data ? JSON.stringify(data.data) : '')) || data.content || ''; }
const k = Math.min(Math.max(parseInt(data.k, 10) || 5, 1), 20);
return [{ json: { task_id: String(task_id), operation, kind, project, text: String(text), query: String(data.query || ''), k, meta } }];

const input = $input.first().json;
return [{
  json: {
    success: false,
    agent: "Agent Knowledge/Memory",
    task_id: "unknown",
    status: "ERROR",
    error_code: input.error_code,
    error_message: input.error_message,
    approved_for_pipeline: false,
    timestamp: input.timestamp
  }
}];

const input = $input.first().json;
const MEM_URL = ($env && $env.MEMORY_URL) || 'http://167.86.93.31:4002';
const MEM_TOKEN = ($env && $env.MEMORY_TOKEN) || '';
const MISTRAL_KEY = ($env && ($env.MISTRAL_API_KEY || $env.MISTRAL_API_KEY_2)) || '';
const text = String(input.text || '').slice(0, 8000);
const base = { task_id: input.task_id, operation: 'WRITE', category: input.kind, project: input.project, timestamp: new Date().toISOString() };
if (!text) return [{ json: Object.assign({}, base, { status: 'STORED', stored: false, message: 'Texte vide — rien à mémoriser' }) }];
try {
  const emb = await this.helpers.httpRequest({ method: 'POST', url: 'https://api.mistral.ai/v1/embeddings', headers: { 'Authorization': 'Bearer ' + MISTRAL_KEY, 'Content-Type': 'application/json' }, body: { model: 'mistral-embed', input: [text] }, json: true, timeout: 15000 });
  const vector = emb && emb.data && emb.data[0] && emb.data[0].embedding;
  if (!Array.isArray(vector)) throw new Error('embedding indisponible');
  const stored = await this.helpers.httpRequest({ method: 'POST', url: MEM_URL + '/store', headers: { 'Content-Type': 'application/json', 'X-Memory-Token': MEM_TOKEN }, body: { kind: input.kind, project: input.project, text: text, vector: vector, meta: input.meta || {} }, json: true, timeout: 15000 });
  return [{ json: Object.assign({}, base, { status: 'STORED', stored: true, entry_id: stored && stored.id, dim: stored && stored.dim, message: 'Entrée mémorisée (' + input.kind + '/' + input.project + ')' }) }];
} catch (e) {
  // Non bloquant : la mémoire est advisory, elle ne fait jamais échouer le pipeline.
  return [{ json: Object.assign({}, base, { status: 'STORED', stored: false, degraded: true, message: 'Mémoire indisponible (' + (e && e.message) + ') — ignoré (non bloquant)' }) }];
}

const input = $input.first().json;
const MEM_URL = ($env && $env.MEMORY_URL) || 'http://167.86.93.31:4002';
const MEM_TOKEN = ($env && $env.MEMORY_TOKEN) || '';
const MISTRAL_KEY = ($env && ($env.MISTRAL_API_KEY || $env.MISTRAL_API_KEY_2)) || '';
const query = String(input.query || input.text || '').slice(0, 8000);
const k = Math.min(Math.max(parseInt(input.k, 10) || 5, 1), 20);
const base = { task_id: input.task_id, operation: 'READ', category: input.kind, project: input.project, timestamp: new Date().toISOString() };
if (!query) return [{ json: Object.assign({}, base, { status: 'RETRIEVED', entries: [], count: 0, message: 'Requête vide' }) }];
try {
  const emb = await this.helpers.httpRequest({ method: 'POST', url: 'https://api.mistral.ai/v1/embeddings', headers: { 'Authorization': 'Bearer ' + MISTRAL_KEY, 'Content-Type': 'application/json' }, body: { model: 'mistral-embed', input: [query] }, json: true, timeout: 15000 });
  const vector = emb && emb.data && emb.data[0] && emb.data[0].embedding;
  if (!Array.isArray(vector)) throw new Error('embedding indisponible');
  const body = { vector: vector, k: k };
  if (input.project) body.project = input.project;
  if (input.kind) body.kind = input.kind;
  const res = await this.helpers.httpRequest({ method: 'POST', url: MEM_URL + '/search', headers: { 'Content-Type': 'application/json', 'X-Memory-Token': MEM_TOKEN }, body: body, json: true, timeout: 15000 });
  const results = (res && res.results) || [];
  return [{ json: Object.assign({}, base, { status: 'RETRIEVED', entries: results, count: results.length, message: results.length + ' entrée(s) pertinente(s)' }) }];
} catch (e) {
  return [{ json: Object.assign({}, base, { status: 'RETRIEVED', entries: [], count: 0, degraded: true, message: 'Mémoire indisponible (' + (e && e.message) + ') — 0 résultat (non bloquant)' }) }];
}

const input = $input.first().json;
const isSuccess = input.status === 'STORED' || input.status === 'RETRIEVED';

return [{
  json: {
    success: isSuccess,
    agent: "Agent Knowledge/Memory",
    task_id: input.task_id,
    status: isSuccess ? "PASS" : "FAIL",
    global_score: isSuccess ? 100 : 0,
    approved_for_pipeline: isSuccess,
    language: "javascript",
    critical_issues: [],
    warnings: [],
    recommendations: isSuccess
      ? [`Opération ${input.operation} réussie`]
      : [`Échec de l'opération ${input.operation}`],
    summary: input.message || `Opération ${input.operation}`,
    dimensions: { security: { score: 100 }, quality: { score: 100 } },
    operation: input.operation,
    entry_id: input.entry_id || null,
    timestamp: input.timestamp || new Date().toISOString()
  }
}];
